// ---------- caixas: confirmar e perguntar (o app instalado nao tem confirm()/prompt() do navegador) ----------
function caixaAtlas(titulo,corpo,botoes){return new Promise(ok=>{const old=$("#cxa");if(old)old.remove();let feito=false;const fim=v=>{if(feito)return;feito=true;F.remove();document.removeEventListener("keydown",tec,true);ok(v)},tec=e=>{if(e.key==="Escape"){e.preventDefault();e.stopPropagation();fim(null)}};
  const F=h("div",{id:"cxa",role:"dialog","aria-modal":"true","aria-label":titulo,onclick:e=>{if(e.target===F)fim(null)}},h("div",{class:"cxa-caixa"},h("h2",{},titulo),h("div",{class:"cxa-corpo"},corpo),h("div",{class:"cxa-rod"},botoes.map(b=>h("button",{type:"button",class:b.cls||"",onclick:()=>fim(b.v!==undefined?b.v:true)},b.txt)))));
  document.body.append(F);document.addEventListener("keydown",tec,true);const f=F.querySelector("input,.primary,.danger")||F.querySelector("button");if(f)f.focus();F._fim=fim})}
const confirma=(titulo,txt,sim,perigo)=>caixaAtlas(titulo,h("p",{},txt),[{txt:"Cancelar",cls:"ghost",v:false},{txt:sim||"Confirmar",cls:perigo?"danger":"primary",v:true}]);
